self.KB_CONTENT["card:779575"]={"id":"card:779575","ty":"card","sourceId":"779575","title":"『Body基本資料建立作業』的作業目的為何？","ver":"GP4以上","topic":"品號","keywords":["品號","透過","編碼"],"y":"explain","answer":"若有新Body之建置需求時，透過此作業做資料的輸入及管理。當此作業確認後，會依自動編碼設定作業之編碼，自動產生相關之IDL品號。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
