self.KB_CONTENT["card:780786"]={"id":"card:780786","ty":"card","sourceId":"780786","title":"『資料匯出入欄位設定作業』中的『資料轉換 (TF010)』為何？","ver":"GP4以上","topic":"單身","keywords":["單身","出入"],"y":"other","answer":"* 若「實體型態」顯示為「Y」、「YM」或「YMD」，則「資料轉換」欄位會打勾，並可輸入子單身。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
