self.KB_CONTENT["card:750691"]={"id":"card:750691","ty":"card","sourceId":"750691","title":"『報表格式設定建立作業』中的『百分比碼 (TF020)』為何？","ver":"iGP","topic":"科目","keywords":["科目"],"y":"other","answer":"* 只能輸入+、-、0、空白。* +：表示當分母，會用該科目去做加後的值來當分母。-：表示當分母，會用該科目去做減後的值來當分母。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
