self.KB_CONTENT["card:750804"]={"id":"card:750804","ty":"card","sourceId":"750804","title":"『未結案應收明細表』中的『列印品名規格及客戶品號』為何？","ver":"iGP","topic":"明細表","keywords":["明細表","品號","客戶","結案"],"y":"other","answer":"* 當有列印帳款明細資料及商品明細時，此欄位才可輸入列印此商品之品名規格及客戶品號資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
