self.KB_CONTENT["card:754606"]={"id":"card:754606","ty":"card","sourceId":"754606","title":"『客戶資料建立作業』中的『客戶英文全名』為何？","ver":"iGP","topic":"客戶","keywords":["客戶"],"y":"other","answer":"* 輸入客戶公司英文名稱，一共可以輸入72個字元。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
