self.KB_CONTENT["field:884291"]={"id":"field:884291","ty":"field","sourceId":"884291","title":"相同交貨日彙總產生","ver":"AiGP1.1.3.以上","topic":"","keywords":[],"job":"請購資料更新作業","code":"","answer":"若有勾選【相同交貨日彙總產生】系統會先抓(1)品號廠商建立作業的採購單價 (2)品號資料建立作業的最近進價 (3)品號資料建立作業的標準進價，抓不到就為0， 若沒有勾選時，才是直接抓請購維護單價","file":"fields.jsonl"};
